D[23060]={"Bonescythe Ring",4,92,60,1,6,15,"INV_Jewelry_Ring_51Naxxramas",{agi=20,hit=1,sta=10,str=20},"Binds when picked up\nUnique-Equipped\nFinger\n+20 Strength\n+20 Agility\n+10 Stamina\nClasses: Rogue\nRequires Level 60\nEquip: Improves your chance to hit with melee and ranged attacks by 1%.\n \nBonescythe Armor (0/0)\n \n(2) Set: Your normal melee swings have a chance to Invigorate you, healing you for 90 to 110.\n(4) Set: Your Backstab, Sinister Strike, and Hemorrhage critical hits cause you to regain 5 energy.\n(6) Set: Reduces the threat from your Backstab, Sinister Strike, Hemorrhage, and Eviscerate abilities.\n(8) Set: Your Eviscerate has a chance per combo point to reveal a flaw in your opponent's armor, granting a 100% critical hit chance for your next Backstab, Sinister Strike, or Hemorrhage.",0}
D[23061]={"Ring of Faith",4,92,60,1,6,15,"INV_Jewelry_Ring_51Naxxramas",{heal=55,int=16,sdmg=19,spi=16},"Binds when picked up\nUnique-Equipped\nFinger\n+16 Intellect\n+16 Spirit\nClasses: Priest\nRequires Level 60\nEquip: Increases healing done by up to 55 and damage done by up to 19 for all magical spells and effects.\n \nVestments of Faith (0/9)\n  Belt of Faith\n  Bindings of Faith\n  Circlet of Faith\n  Gloves of Faith\n  Leggings of Faith\n  Robe of Faith\n  Sandals of Faith\n  Shoulderpads of Faith\n  Ring of Faith\n \n(2) Set: Reduces the mana cost of your Renew spell by 12%.\n(4) Set: On Greater Heal critical hits, your target will gain Armor of Faith, absorbing up to 500 damage.\n(6) Set: Reduces the threat from your healing spells.\n(8) Set: Each spell you cast can trigger an Epiphany, increasing your mana regeneration by 30 for 30 sec.",0}
D[23062]={"Frostfire Ring",4,92,60,1,6,15,"INV_Jewelry_Ring_51Naxxramas",{int=10,scrit=1,sp=30,sta=10},"Binds when picked up\nUnique-Equipped\nFinger\n+10 Stamina\n+10 Intellect\nClasses: Mage\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 30.\nEquip: Improves your chance to get a critical strike with spells by 1%.\n \nFrostfire Regalia (0/9)\n  Frostfire Belt\n  Frostfire Bindings\n  Frostfire Circlet\n  Frostfire Gloves\n  Frostfire Leggings\n  Frostfire Robe\n  Frostfire Sandals\n  Frostfire Shoulderpads\n  Frostfire Ring\n \n(2) Set: Reduces cooldown on your Evocation by 1 minute.\n(4) Set: Gives your Mage Armor a chance when struck by a harmful spell to increase resistance against that school of magic by 35 for 30 sec.\n(6) Set: Your damage spells have a chance to cause your target to take up to 200 increased damage from subsequent spells.\n(8) Set: Your damage spells have a chance to displace you, causing the next spell cast to generate no threat.",0}
D[23063]={"Plagueheart Ring",4,92,60,1,6,15,"INV_Jewelry_Ring_51Naxxramas",{sp=29,sta=24},"Binds when picked up\nUnique-Equipped\nFinger\n+24 Stamina\nClasses: Warlock\nRequires Level 60\nEquip: Increases damage and healing done by magical spells and effects by up to 29.\n \nPlagueheart Raiment (0/9)\n  Plagueheart Belt\n  Plagueheart Bindings\n  Plagueheart Circlet\n  Plagueheart Gloves\n  Plagueheart Leggings\n  Plagueheart Robe\n  Plagueheart Sandals\n  Plagueheart Shoulderpads\n  Plagueheart Ring\n \n(2) Set: Your Shadow Bolts now have a chance to heal you for 270 to 330.\n(4) Set: Increases damage caused by your Corruption by 12%.\n(6) Set: Your spell critical hits generate 25% less threat.  In addition, Corruption, Immolate, Curse of Agony, and Siphon Life generate 25% less threat.\n(8) Set: Reduces health cost of your Life Tap by 12%.",0}
D[23064]={"Ring of the Dreamwalker",4,92,60,1,6,15,"INV_Jewelry_Ring_51Naxxramas",{heal=37,int=16,sdmg=13,spi=16,sta=16},"Binds when picked up\nUnique-Equipped\nFinger\n+16 Stamina\n+16 Intellect\n+16 Spirit\nClasses: Druid\nRequires Level 60\nEquip: Increases healing done by up to 37 and damage done by up to 13 for all magical spells and effects.\n \nDreamwalker Raiment (0/0)\n \n(2) Set: Your Rejuvenation ticks have a chance to restore 60 mana, 8 energy, or 2 rage to your target.\n(4) Set: Reduces the mana cost of your Healing Touch, Regrowth, Rejuvenation,  and Tranquility spells by 3%.\n(6) Set: Your initial cast and Regrowth ticks will increase the maximum health of your target by up to 50, stacking up to 7 times.\n(8) Set: On Healing Touch critical hits, you regain 30% of the mana cost of the spell.",0}
